pub fn an_or_a_named(ty: &str) -> String {
    if ty.starts_with('i') || ty.starts_with('a') || ty.starts_with('e') || ty.starts_with('o') || ty.starts_with('I') || ty.starts_with('A') || ty.starts_with('E') || ty.starts_with('O') { return "an".to_owned(); }
    "a".to_owned()
}

pub(crate) fn arith_symbol(op: BinaryOp) -> String {
    match op {
        BinaryOp::Add => "+".to_owned(),
        BinaryOp::Sub => "-".to_owned(),
        BinaryOp::Mul => "*".to_owned(),
        BinaryOp::Div => "/".to_owned(),
        _ => "%".to_owned(),
    }
}

pub(crate) fn arith_extend_text(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, target: &Expr, value: &Expr, compound: bool) -> String {
    if !compound { return "a.extend(b)".to_owned(); }
    match target {
        Expr::Variable(bound, _) => { let bound = *bound; format!("{}.extend({})", world.words.resolve(bound), written_expression(world.words, value)) },
        _ => "a.extend(b)".to_owned(),
    }
}

pub(crate) fn arith_numeric_fields(fields: &[FieldContract]) -> Vec<String> {
    let mut numeric: Vec<String> = vec![];
    for field in fields.iter() { if arith_a_plain_number(&field.ty) { numeric.push(field.name.to_owned()); } }
    numeric
}

pub(crate) fn arith_a_plain_number(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => args.is_empty() && a_number_name(name),
        _ => false,
    }
}

pub(crate) fn arith_a_variable(side: &Expr, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>) -> Option<String> {
    match side {
        Expr::Variable(bound, _) => { let bound = *bound; Some(world.words.resolve(bound).to_owned()) },
        _ => None,
    }
}

pub(crate) fn arith_a_number_literal(expr: &Expr) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_, _) => true,
        Expr::MethodCall { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); arith_an_int_literal(receiver) },
        _ => false,
    }
}

pub(crate) fn arith_an_int_literal(expr: &Expr) -> bool { matches!(expr, Expr::LitInt { .. }) }

pub(crate) fn arith_a_named_call(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, expr: &Expr, called: &str) -> bool {
    match expr {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); arith_the_variable_named(world, func, called) },
        _ => false,
    }
}

pub(crate) fn arith_the_variable_named(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, expr: &Expr, name: &str) -> bool {
    match expr {
        Expr::Variable(n, _) => { let n = *n; world.words.resolve(n) == name },
        _ => false,
    }
}

pub(crate) fn arith_structural(expr: &Expr) -> bool { matches!(expr, Expr::Binary { .. } | Expr::Unary { .. } | Expr::If { .. } | Expr::Block(_, _) | Expr::Match { .. } | Expr::Select(_, _) | Expr::Return(_, _) | Expr::Throw(_, _) | Expr::TryCatch { .. } | Expr::Range { .. } | Expr::Continue(_) | Expr::Break(_)) }

pub(crate) fn arith_a_name(expr: &Expr) -> bool { matches!(expr, Expr::Variable(_, _)) }

pub(crate) fn arith_shown(written: &str) -> String {
    if (written.chars().count() as i64) <= 60 { return written.to_owned(); }
    let mut shown: String = "".to_owned();
    let mut count = 0;
    for c in written.chars() {
        if count < 57 { shown.push_str(&c.to_string()); }
        count += 1;
    }
    shown.push_str("...");
    shown
}

